async function immediateBurial(reason){life();bot.pathfinder.setGoal(null);bot.clearControlStates();for(let k=0;k<12&&!bot.entity.onGround;k++)await tick(1);const q=bot.entity.position.floored().offset(0,-1,0);if(!bot.entity.onGround||!cheapColumn(q))return false;await centerDrop(q);if(!cheapColumn(q))return false;global.P1DownPending={feet:q.offset(0,-2,0),roof:q,at:Date.now()};let steps=0;try{for(let y=0;y>=-2;y--){life();const b=bot.blockAt(q.offset(0,y,0)),pick=bot.inventory.items().find(i=>i.name.endsWith('_pickaxe'));if(pick&&!['dirt','grass_block','sand'].includes(b.name))await bot.equip(pick,'hand');else await bot.unequip('hand');await bot.dig(b,true);steps++;for(let k=0;k<35&&(!bot.entity.onGround||Math.abs(bot.entity.position.y-q.y-y)>.12);k++)await tick(1);if(!bot.entity.onGround||Math.abs(bot.entity.position.y-q.y-y)>.12)throw Error('BURIAL_SETTLE')}for(let k=0;k<30&&!bot.inventory.items().some(i=>stableNames.includes(i.name));k++)await tick(1);const item=bot.inventory.items().find(i=>stableNames.includes(i.name));if(!item)throw Error('BURIAL_NO_CAP');await bot.equip(item,'hand');const rd=dirs.find(d=>full(bot.blockAt(q.plus(d))));if(!rd)throw Error('BURIAL_NO_ANCHOR');await bot._placeBlockWithOptions(bot.blockAt(q.plus(rd)),rd.scaled(-1),{forceLook:true});await tick(4);if(!shell(q.offset(0,-2,0)))throw Error('BURIAL_HULL');const inside=foes().filter(e=>Math.abs(e.position.x-q.x-.5)<.85&&Math.abs(e.position.z-q.z-.5)<.85&&e.position.y>=q.y-2.5&&e.position.y<q.y);if(inside.length)throw Error('BURIAL_OCCUPIED_'+inside.map(e=>e.name));global.P1Overland=global.P1DownPending;global.P1DownPending=null;console.log('IN_PROGRAM_BURIAL_VERIFIED',reason,bot.entity.position,bot.health);return true;}catch(e){console.log('BURIAL_ERROR',steps,e.message,JSON.stringify({q,p:bot.entity.position,ground:bot.entity.onGround,v:bot.entity.velocity,blocks:[0,-1,-2].map(y=>[y,bot.blockAt(q.offset(0,y,0))?.name])}));if(steps===3&&await rescueCap())return true;throw e;}}
function guardedMovement(sprint=false){const hazards=foes();const m=new Movements(bot);m.canDig=true;for(const b of bot.registry.blocksArray)if(!b.name.endsWith('_leaves')&&!['snow','short_grass','fern'].includes(b.name))m.blocksCantBreak.add(b.id);m.canOpenDoors=false;m.allowSprinting=sprint;m.allowParkour=false;m.allow1by1towers=false;m.scafoldingBlocks=[];m.maxDropDown=3;for(const n of['water','lava','fire','soul_fire','magma_block','sweet_berry_bush','powder_snow','cactus','nether_portal'])if(bot.registry.blocksByName[n])m.blocksToAvoid.add(bot.registry.blocksByName[n].id);m.exclusionAreasStep.push(b=>{const p=b.position||new Vec3(b.x,b.y,b.z);let c=0;for(const e of hazards){if(Math.abs(e.position.y-p.y)>3&&!['skeleton','stray','witch'].includes(e.name))continue;const d=e.position.distanceTo(p),r=e.name==='creeper'?11:['skeleton','stray','witch'].includes(e.name)?16:7;if(d<r)c+=(r-d)*20;}return c});bot.pathfinder.setMovements(m);bot.pathfinder.thinkTimeout=500;}
async function guardedWalk(ms=60000,forceAfterMs=null,target={x:148.5,z:2212.5},nightTrial=false){const hp0=bot.health;let hurt=false,buried=false,phase='WALK',flee=false,lastPlan=0,started=Date.now(),last=bot.entity.position.clone(),progress=Date.now();const onHealth=()=>{if(bot.health<hp0-.25)hurt=true};bot.on('health',onHealth);try{guardedMovement();while(Date.now()-started<ms){life();if(Math.hypot(target.x-bot.entity.position.x,target.z-bot.entity.position.z)<.7){phase='TARGET';break}const e=contactThreat(),late=!nightTrial&&bot.time.timeOfDay>=10000,forced=forceAfterMs!==null&&Date.now()-started>=forceAfterMs;const shouldBury=e||hurt||late||forced||Date.now()-started>ms-8000;if(shouldBury){const why=e?'PROXIMITY_'+e.name:hurt?'HURT':late?'BEFORE_NIGHT':forced?'CONTROLLED':'BUDGET';if(await immediateBurial(why)||await surfaceBox(why)){buried=true;phase='BURIED';break}flee=!!e||hurt;}
