async function alignAxis(axis,target,max=45){for(let k=0;k<max&&Math.abs(bot.entity.position[axis]-target)>.045;k++){await bot.lookAt(bot.entity.position.offset(axis==="x"?Math.sign(target-bot.entity.position.x)*5:0,1.4,axis==="z"?Math.sign(target-bot.entity.position.z)*5:0),true);bot.setControlState("sneak",true);bot.setControlState("forward",true);await tick(1);bot.clearControlStates();await tick(2)}if(Math.abs(bot.entity.position[axis]-target)>.09)throw Error("ALIGN_ACTUAL "+axis)}
async function transit(mode){bot.pathfinder.setGoal(null);bot.clearControlStates();const d=new Vec3(6,67,81);if(bot.entity.position.distanceTo(d)>5)throw Error("DOOR_START_FAR");if(mode==="exit"){await alignAxis("x",6.59375);await alignAxis("z",82.6)}else await alignAxis("x",6.59375);let b=bot.blockAt(d);if(b.name!=="spruce_door"||b.getProperties().facing!=="north")throw Error("DOOR_GEOMETRY");if(!b.getProperties().open){await bot.activateBlock(b);await tick(7)}await bot.lookAt(bot.entity.position.offset(0,1.4,mode==="exit"?-10:10),true);bot.setControlState("forward",true);try{for(let k=0;k<80;k++){await tick(1);if(mode==="exit"?bot.entity.position.z<79.5:bot.entity.position.z>82.3)break}}finally{bot.clearControlStates()}await tick(5);if(mode==="exit"?bot.entity.position.z>=79.6:bot.entity.position.z<=82.15||(bot.entity.position.y<67||bot.entity.position.y>67.65))throw Error("TRANSIT_ACTUAL");b=bot.blockAt(d);if(b.getProperties().open){await bot.activateBlock(b);await tick(10)}if(bot.blockAt(d).getProperties().open)throw Error("DOOR_NOT_CLOSED");console.log("TRANSIT_CLOSED_ACTUAL",mode,bot.entity.position);bot.chat("P1_"+mode+"_ACTUAL_CLOSED door6 KEEP_P1_WRITER_UNTIL_OPERATION_END "+bot.entity.position+" HP"+bot.health+" no pendingdoorcontrols; nextfieldphaseown.");}
async function surfaceBox(reason){life();bot.pathfinder.setGoal(null);bot.clearControlStates();if(!bot.entity.onGround||bot.entity.isInWater)return false;const p=bot.entity.position.floored(),floor=bot.blockAt(p.offset(0,-1,0));if(!full(floor)||['magma_block','lava'].includes(floor.name))return false;const order=[...dirs];const enemy=foes()[0];if(enemy){const dx=enemy.position.x-p.x,dz=enemy.position.z-p.z;order.sort((a,b)=>(b.x*dx+b.z*dz)-(a.x*dx+a.z*dz))}const missing=[];for(const d of order){for(const y of[-1,0,1]){const q=p.plus(d).offset(0,y,0),b=bot.blockAt(q);if(full(b))continue;if(!['air','cave_air','snow','short_grass','fern','tall_grass'].includes(b.name)&&!(y===-1&&b.name==='water'))return false;missing.push(q)}}const dirt=()=>bot.inventory.items().filter(i=>i.name==='dirt').reduce((a,i)=>a+i.count,0);if(dirt()<missing.length+2)return false;await centerDrop(p);async function put(q,ref,face){if(full(bot.blockAt(q)))return;const it=bot.inventory.items().find(i=>i.name==='dirt');if(!it)throw Error('BOX_NO_DIRT');await bot.equip(it,'hand');await bot._placeBlockWithOptions(bot.blockAt(ref),face,{forceLook:true});await tick(2);if(!full(bot.blockAt(q)))throw Error('BOX_BLOCK_ACK_'+q)}
